bool is_palindrome(const string& s, int left, int right) {
    while (left < right) {
        if (s[left++] != s[right--]) {
            return false;
        }
    }
    return true;
}

void split(const string& s, int start, vector<string>& chosen, vector<vector<string>>& out) {
    if (start == (int)s.size()) {
        out.push_back(chosen);
        return;
    }
    for (int end = start; end < (int)s.size(); ++end) {
        if (is_palindrome(s, start, end)) {
            chosen.push_back(s.substr(start, end - start + 1));
            split(s, end + 1, chosen, out);
            chosen.pop_back();
        }
    }
}

vector<vector<string>> palindrome_partitions(string s) {
    vector<vector<string>> out;
    vector<string> chosen;
    split(s, 0, chosen, out);
    sort(out.begin(), out.end());
    return out;
}

